var a=`1273-ducana`;var i=`world-1273`;var n=`AG`;var o=`central-america-caribbean`;var r=8;var s=107;var l={en:`Ducana`,ua:`Дукана`};var u={en:`Ducana is a dish from Antigua and Barbuda featuring sweet potato, coconut, coconut milk, banana leaf. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Дукана, страва кухні країни Антигуа і Барбуда з такими основними складниками: батат, кокос, кокосове молоко, банановий лист. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var g=[{en:`Peel and coarsely grate the listed vegetables; squeeze out excess moisture so the mixture will hold together.`,ua:`Очистьте й натріть овочі на грубій тертці; відіжміть зайву рідину, щоб маса тримала форму.`,t:[`peeling`,`coarse-grating`,`squeezing-out-moisture`],m:14,i:[[`sweet-potato`,720,`g`],[`coconut`,280,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:10,i:[[`white-granulated-sugar`,130,`g`],[`ground-cinnamon`,5,`g`],[`ground-nutmeg`,3,`g`],[`coconut-milk`,240,`ml`]]},{en:`Place a portion of prepared filling on each leaf or wrapper, tuck in the sides and roll tightly into neat parcels.`,ua:`Викладіть порцію готової начинки на кожен листок або обгортку, загорніть боки й скрутіть щільні акуратні рулетики.`,t:[`rolling-stuffed-food`],m:15,i:[[`banana-leaf`,8,`leaf`]]},{en:`Steam the already prepared parcels or mixture over gently boiling water for approximately 65 minutes, until fully cooked or set.`,ua:`Готуйте раніше підготовлені згортки або масу на парі над слабким кипінням близько 65 хвилин до готовності.`,t:[`steaming`],m:65,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`unsalted-butter`,35,`g`]]}];var d={slug:a,id:i,country:`AG`,region:o,servings:8,minutes:107,title:l,text:u,steps:g};export{n as country,d as default,i as id,s as minutes,o as region,r as servings,a as slug,g as steps,u as text,l as title};